insert into public.overview_blocks (id, project_id, label, body, sort_order) values ('ace36152-53e4-5e1d-a6e4-e7da55f761af', 'db27acde-e638-5f6e-a4e1-b36501661b91', 'Big idea', '“Skech Your Vibe”: creative freedom can be found anywhere, from city alleys to the beach to street music. Tagline: “Skech in style, feel the vibe.”', 0);
insert into public.overview_blocks (id, project_id, label, body, sort_order) values ('f705cefe-0cb7-557f-ad0a-f1e87be5a06d', 'db27acde-e638-5f6e-a4e1-b36501661b91', 'Story', 'One character’s journey in four parts: alley, beach, busking band and night city. His T-shirt artwork turns into 2D animation at each stop.', 1);
insert into public.overview_blocks (id, project_id, label, body, sort_order) values ('de84ce4b-9748-51a9-a443-ff61ad3f83aa', 'db27acde-e638-5f6e-a4e1-b36501661b91', 'Look and cast', 'Stylised cinematic realism, with a live-action look mixed with animated 2D Cloakwork artwork. 8 characters: 6 male, 2 female.', 2);
insert into public.overview_blocks (id, project_id, label, body, sort_order) values ('c04043c5-3ff6-5ced-adb6-78f81e4f2ca5', 'db27acde-e638-5f6e-a4e1-b36501661b91', 'Timeline', 'Planned: storyboard 10 Jun to final approval 23 Jun 2026. Client review rounds continued to 10 Jul 2026.', 3);
insert into public.overview_blocks (id, project_id, label, body, sort_order) values ('0eb696ce-4c10-5ca3-a408-85df8a583701', 'eae963eb-14a8-5e6e-a711-cc63ec75c51c', 'Audience', 'Young generation: rural mass on the East Coast, and urban households in the Klang Valley.', 0);
insert into public.overview_blocks (id, project_id, label, body, sort_order) values ('05ae3225-3949-5e00-a6d7-3efbbcc27d28', 'eae963eb-14a8-5e6e-a711-cc63ec75c51c', 'Big idea', 'Superhero-film energy with human-like characters in forward-futuristic fashion, shown training their abilities. Pillars: Fashion, Action, Attitude.', 1);
insert into public.overview_blocks (id, project_id, label, body, sort_order) values ('8fe412d8-12e3-539d-ab96-e89f70b7094c', 'eae963eb-14a8-5e6e-a711-cc63ec75c51c', 'Look and cast', 'Stylised reality: realistic characters in a bright orange-sky metropolis, never dark or dystopian.', 2);
insert into public.overview_blocks (id, project_id, label, body, sort_order) values ('be676130-96ff-5269-ad34-3d117202f33d', 'eae963eb-14a8-5e6e-a711-cc63ec75c51c', 'Timeline', 'Brief 25 Mar 2026, target final approval 10 Apr, live date 13 Apr. Final language and format submissions ran to 13 May 2026.', 3);
insert into public.overview_blocks (id, project_id, label, body, sort_order) values ('a43b31af-4c84-5559-af16-42743f041327', '3838ffd4-2370-528e-a0a0-bb85caa7a0e5', 'Big idea', '“Because family comes first, we made priority shareable.” It places UMobile ULTRA alongside other premium choices, like flying business class.', 0);
insert into public.overview_blocks (id, project_id, label, body, sort_order) values ('4d1c37f1-aef3-58ac-a4d7-275ff40794dc', '3838ffd4-2370-528e-a0a0-bb85caa7a0e5', 'Cast', 'A mother in her late 20s and her 2-year-old son, with a pan-Asian look that represents both Malay and Chinese audiences in Malaysia.', 1);
insert into public.overview_blocks (id, project_id, label, body, sort_order) values ('f1920ae9-6b61-56b3-adc2-7f8e41fe7670', '3838ffd4-2370-528e-a0a0-bb85caa7a0e5', 'Versions', 'West Coast: the approved key visual. East Coast: the mother wears a modern tudung or hijab look that appeals to the T20 income audience.', 2);
insert into public.overview_blocks (id, project_id, label, body, sort_order) values ('eca38df9-27fd-51db-a152-1cfc6ffcb10a', '3838ffd4-2370-528e-a0a0-bb85caa7a0e5', 'Timeline and usage', 'Hi-res key visual due 12 Mar 2026; launch 7 Apr 2026. Usage in Malaysia for 1 year across BTL, digital, website, social media and on-ground.', 3);
insert into public.overview_blocks (id, project_id, label, body, sort_order) values ('9435467c-56dd-5eea-ab0e-6eb9ee23a10d', '844cd0cc-48b1-5d10-a7cc-a5d98abcb492', 'Big idea', '“From Buffer to Bliss”: the lag and low-fi sound of a bad connection flips into crisp, instant, high-speed sound. Line: “Why settle for a life on buffer?”', 0);
insert into public.overview_blocks (id, project_id, label, body, sort_order) values ('97dc321d-456b-53b8-af6d-827aa5c9000d', '844cd0cc-48b1-5d10-a7cc-a5d98abcb492', 'Music', 'Two track ideas: re-engineer the Ultra superhero track, or flip U Mobile’s own jingle. Both move from a slow, muted start to a high-energy payoff.', 1);
insert into public.overview_blocks (id, project_id, label, body, sort_order) values ('20ab6e33-3321-5f7c-a94a-b5b58b0732f4', '844cd0cc-48b1-5d10-a7cc-a5d98abcb492', 'Timeline', 'Feedback on 25 May, 8 Jun and 12 Jun 2026, ending with a final English track and a final BM track.', 2);
insert into public.overview_blocks (id, project_id, label, body, sort_order) values ('39c1688e-45f2-5870-a382-fa132a1da337', '7486adde-0226-57bf-a157-e83a7133a9e6', 'Big idea', '“Your Screen. Your World.” The phone screen is a portal: press play and you enter the action as the hero. Ultra Prepaid gives you passage, not just data.', 0);
insert into public.overview_blocks (id, project_id, label, body, sort_order) values ('0d4a1557-7108-58d1-ac59-502dd9e0fbc6', '7486adde-0226-57bf-a157-e83a7133a9e6', 'Story', 'Each film pulls the viewer from a phone screen into a hero moment in first person, then out to a third-person view and the product end frame.', 1);
insert into public.overview_blocks (id, project_id, label, body, sort_order) values ('aec5c1eb-fb5a-5996-af33-a9fb46b4c6b7', '7486adde-0226-57bf-a157-e83a7133a9e6', 'Six moments', 'Football, motorsport, esports gaming, DJ music, a birthday video call with family, and a K-drama scene, matched to what each community enjoys.', 2);
insert into public.overview_blocks (id, project_id, label, body, sort_order) values ('588fe608-5bd2-5c53-a5cc-2d39e8dda16c', '7486adde-0226-57bf-a157-e83a7133a9e6', 'Timeline', 'Storyboard rounds 22 to 29 Jul, video rounds 4 to 26 Aug 2026, then final videos for Indonesia, Nepal and Bangladesh.', 3);
insert into public.overview_blocks (id, project_id, label, body, sort_order) values ('e0c74bcb-5b4b-56cc-a872-fe557c957ccd', '5e29e069-00ae-527b-a8b6-64bb6db68e46', 'Big idea', '“When Life Gives You Twists”: vertical dramas inspired by Chinese and Korean TikTok dramas. Melodramatic, humorous and fast-paced.', 0);
insert into public.overview_blocks (id, project_id, label, body, sort_order) values ('42d525fd-bfc9-5796-a645-041d13889b77', '5e29e069-00ae-527b-a8b6-64bb6db68e46', 'Series', '4 episodes, one scam each: fake job offer, lucky draw prize, investment and love scam. Key message: scams prey on emotions, so pause.', 1);
insert into public.overview_blocks (id, project_id, label, body, sort_order) values ('b3e8d112-6596-5e08-adbd-bf14da240436', '5e29e069-00ae-527b-a8b6-64bb6db68e46', 'Second concept', 'Also pitched: “Shadow Lines”, a Black Mirror-inspired suspense series built around everyday phone screens and SMS threads.', 2);
insert into public.overview_blocks (id, project_id, label, body, sort_order) values ('036f087d-882e-59b3-ac36-d2a822a17cdd', '5e29e069-00ae-527b-a8b6-64bb6db68e46', 'Timeline', 'Review rounds from 28 Aug to 14 Sep 2026, then the vertical version adapted on 28 Sep 2026. Episode 1 approved.', 3);
insert into public.overview_blocks (id, project_id, label, body, sort_order) values ('88ca2933-9986-5e26-ab0d-267655f252b6', 'f6e59981-235c-51ee-a383-9034aede7f2c', 'Astro touchpoints', 'Stadium Astro, Syok podcast, Sooka, KULT Offside, Awani and AstroGO’s Ikatan Terlarang appear naturally through his day.', 0);
insert into public.overview_blocks (id, project_id, label, body, sort_order) values ('c6a91a99-27f0-5cc2-a912-ecdfd060a332', 'f6e59981-235c-51ee-a383-9034aede7f2c', 'Story arc', 'A full circle: the day starts and ends in bed on his phone, and a watch timelapse from Casio to Rolex shows career growth with Astro.', 1);
insert into public.overview_blocks (id, project_id, label, body, sort_order) values ('286e5bce-5fe9-57a3-a4f2-18e6e2082742', 'f6e59981-235c-51ee-a383-9034aede7f2c', 'Look and sound', 'Wes Anderson-style cinematography and colour palettes, with ASMR sound cues such as clock flips, a running shower and train doors.', 2);
insert into public.overview_blocks (id, project_id, label, body, sort_order) values ('2d897aab-23d3-551e-a364-3d76e0b617bb', 'f6e59981-235c-51ee-a383-9034aede7f2c', 'Brand placement', 'Brands placed inside scenes, including a U Mobile billboard seen from the train and Mamee cup noodles at lunch.', 3);
insert into public.overview_blocks (id, project_id, label, body, sort_order) values ('9ded3ee0-7c30-5344-a589-3bfc5a8ed0f6', '4a01fdae-bf8e-514b-acc7-6ad16f62970e', 'Big idea', '“Bah! Scan DuitNow QR”, with the hero message “Caj 0%, Pilih 1 Bulan”. Localised for Borneo, with bold type and high-contrast orange.', 0);
insert into public.overview_blocks (id, project_id, label, body, sort_order) values ('af9410cb-872d-506a-ab26-fc21c934a707', '4a01fdae-bf8e-514b-acc7-6ad16f62970e', 'Story', 'Three everyday shoppers scanning at the counter: groceries, Sabah handicraft fashion, and gadgets with friends.', 1);
insert into public.overview_blocks (id, project_id, label, body, sort_order) values ('779ea390-2246-53c1-ae68-e82c687c6d4e', '4a01fdae-bf8e-514b-acc7-6ad16f62970e', 'Timeline', 'Storyboard approved at round 12, static OOH approved 17 Apr and DOOH approved 24 Apr 2026.', 2);
insert into public.overview_blocks (id, project_id, label, body, sort_order) values ('6686ff1d-c871-5bf3-a4cb-a92b1935997b', 'd772ee24-5b88-5877-aa2c-7d9f7b25c0b1', 'Big idea', '“More Value in Every Way.” One masterline across three product truths: more rewards (QR Pay), more flexibility (SPayLater), more potential returns (Money+).', 0);
insert into public.overview_blocks (id, project_id, label, body, sort_order) values ('47442940-6510-51fc-a23f-2c3c8ba02c09', 'd772ee24-5b88-5877-aa2c-7d9f7b25c0b1', 'Two directions', 'Say “More” Boldly: big type with lifestyle photography. The Infinite “More”: a flowing wave-style headline with warm everyday moments.', 1);
insert into public.overview_blocks (id, project_id, label, body, sort_order) values ('3dd0e8cf-aa9c-54cd-a2a8-650d8dda5bdc', 'd772ee24-5b88-5877-aa2c-7d9f7b25c0b1', 'Tonality', 'Everyday: real people and everyday experiences at the centre of the brand. Confident: bold, declarative sans-serif headlines. Brand first: polished but friendly, less like a typical e-wallet ad.', 2);
insert into public.overview_blocks (id, project_id, label, body, sort_order) values ('f2aa5c68-2f3a-59dd-a79e-899e73b4f4aa', 'd772ee24-5b88-5877-aa2c-7d9f7b25c0b1', 'Status', 'Draft for discussion, Nov 2026. Direction 1 reached its 7th revision round.', 3);
insert into public.overview_blocks (id, project_id, label, body, sort_order) values ('a54124ab-f5e2-57a9-acc9-818db8ab3b95', 'bce76034-578c-5233-a110-c59766a4d469', 'Big idea', '“Before We Meet, Scents Do”: a playful romance where a couple separated by a wall meet when their scent trails break through.', 0);
insert into public.overview_blocks (id, project_id, label, body, sort_order) values ('387d21d0-513b-57bc-ad7a-2c6139379578', 'bce76034-578c-5233-a110-c59766a4d469', 'Cast and setting', 'A Kadazan-Dusun man for Kaamatan and an Iban woman for Gawai, in traditional attire, against harvest fields and longhouses.', 1);
insert into public.overview_blocks (id, project_id, label, body, sort_order) values ('41ee286f-34a9-5a58-a4b9-b183b69671fb', 'bce76034-578c-5233-a110-c59766a4d469', 'Language', 'Malay copy, with Iban for Sarawak and Dusun for Sabah on the end frame, plus an AI-content disclaimer in Malay.', 2);
insert into public.overview_blocks (id, project_id, label, body, sort_order) values ('79dadb67-e90b-5f3c-a6b1-e463ecb3cd68', 'bce76034-578c-5233-a110-c59766a4d469', 'Timeline', 'Storyboard rounds 8 to 11 May, DOOH review 13 May, final approval 21 to 22 May, live 25 May 2026.', 3);
insert into public.list_items (id, project_id, type, text, sort_order) values ('18c23e4d-b672-5d44-a589-557025225cad', 'db27acde-e638-5f6e-a4e1-b36501661b91', 'deliverable', '60s hero film', 0);
